-- migrate:up
-- Make live the questions 20260824233929_expand_reflections_catalogue meant to
-- add and silently did not.
--
-- WHY. That migration's header promises 528 questions — 428 from the owner's
-- question-bank spreadsheet and 100 new ones — each with an answer_tier and a
-- category. Its INSERT is guarded by NOT EXISTS on lower(btrim(question_text)),
-- and the guard does not look at is_active. 421 of the 528 texts were already
-- in the table: 20251214231106_seed_questions had seeded them under pinned ids,
-- and step 3 of 20260818235602_reflections_functional_catalog had retired them
-- along with the rest of that 709-row catalogue. The guard found a row, so the
-- insert skipped the text. Measured on a freshly migrated database: 107 rows
-- inserted, 421 skipped, and all 421 of those inactive — never asked, never
-- inferred, untiered, still under the eight categories step 4 folded them into,
-- and still labelled created_by_llm. It is the trap
-- 20260824083722_seed_life_details_questions documents for 'How tall are you?',
-- 421 times over.
--
-- WHAT. Repair in place, as that migration did, rather than insert a second row
-- beside each retired one. Each row becomes the row the expand list describes:
-- active, with the list's tier, category and type, and labelled as seed content
-- (is_seed_question, NOT created_by_llm). The spreadsheet is the owner's, not
-- model output, and the label is not cosmetic: ContextGapQuestionService reads
-- a queued created_by_llm question as a recent LLM question and holds back its
-- own generation because of it.
--
-- ORDER. created_at is stamped with the expand migration's own batch time — the
-- one created_at its INSERT gave the rows it did write, since now() is fixed
-- for a transaction. The rotations read that column. Both inference selectors
-- (QuestionService.findUnansweredByUserId, SmartRotationListener) order by
-- tier, then created_at batch, then a round-robin by seed_position
-- (domains/intelligence/questionOrder.ts), and ContextPromptGenerateService
-- takes the five oldest unanswered. Left at the legacy seed's time, these rows
-- would become the oldest active batch and be asked before the whole functional
-- catalogue. Stamped, they sit where the expand insert would have put them:
-- after that catalogue, in one batch with the rest of the expand list. They
-- keep the seed_position 20260930153606 gave them from 20251214231106's list,
-- which runs in the same order as the expand list, so the round-robin still
-- takes them in written order. If no row marks the batch they take this
-- migration's now() instead, which also sorts after the catalogue.
--
-- WHICH ROWS. Matched by the id 20251214231106 pinned AND by text, so only that
-- seed's own row is touched — the same row on every appliance — and only while
-- it still asks this list's question. A row is left alone when:
--   * anybody has answered or queued it (this repo's rule for editing a seed
--     question in place);
--   * it is not in the shape step 3 of 20260818235602 left: shared, retired,
--     labelled created_by_llm and not seed;
--   * an active shared row already asks the same text, so the question is live;
--   * it is a rating scale. 20260825074747 retired those outright ("there is
--     nothing to ask"), and would have retired this list's one — 'On a scale of
--     1 to 10 ... rate your current overall mood?' — had the expand insert
--     written it. Its pattern is repeated below verbatim.
-- On a fresh database that leaves 420 rows: 33 factual, 311 preference and 76
-- narrative.
--
-- NOT CHANGED. evidence_class: 20260825074747 and
-- 20260825185434_sensitive_questions_hand_entry classified rows by text without
-- looking at is_active, so these already carry the class a fresh insert would
-- have got — 15 of the 420 are hand_entry, askable but never inferred.
-- question_id: pinned, and ci.answers cascades from it.
-- frequency_recommendation and context_tags: the expand list sets neither.
--
-- The list below is the expand migration's VALUES list, row for row, with one
-- column added: the id 20251214231106 pinned for the same text, or NULL for the
-- 107 texts that seed never carried. expandedReflectionsReactivation.test.ts
-- re-reads both files and fails if either disagrees with it.
--
-- Idempotent: a repaired row is active, so a re-run matches nothing.

CREATE TEMP TABLE _expanded_reflections (
  question_text      text NOT NULL,
  question_category  text NOT NULL,
  question_type      text NOT NULL,
  answer_tier        text NOT NULL,
  legacy_question_id uuid UNIQUE
) ON COMMIT DROP;


WITH batch AS (
  -- Exactly one row, whose value is NULL when nothing marks the batch. Every row
  -- the expand insert wrote shares one created_at; the most common value, latest
  -- on a tie, still finds it if something else ever seeded one of these texts.
  SELECT (
    SELECT q.created_at
      FROM ci.questions q
      JOIN _expanded_reflections c
        ON lower(btrim(q.question_text)) = lower(btrim(c.question_text))
     WHERE q.is_private_to IS NULL
       AND q.is_seed_question
       AND NOT q.created_by_llm
     GROUP BY q.created_at
     ORDER BY count(*) DESC, q.created_at DESC
     LIMIT 1
  ) AS created_at
)
UPDATE ci.questions q
   SET is_active         = true,
       is_seed_question  = true,
       created_by_llm    = false,
       question_category = c.question_category,
       question_type     = c.question_type,
       answer_tier       = c.answer_tier,
       created_at        = COALESCE(b.created_at, now()),
       updated_at        = now()
  FROM _expanded_reflections c
 CROSS JOIN batch b
 WHERE q.question_id = c.legacy_question_id
   AND lower(btrim(q.question_text)) = lower(btrim(c.question_text))
   AND q.is_private_to IS NULL
   AND NOT q.is_active
   AND q.created_by_llm
   AND NOT q.is_seed_question
   AND q.question_text !~* '(scale of 1|scale of one|from one to ten|1-10|rate how)'
   AND NOT EXISTS (SELECT 1 FROM ci.answers a WHERE a.question_id = q.question_id)
   AND NOT EXISTS (SELECT 1 FROM ci.feed_queue f WHERE f.question_id = q.question_id)
   AND NOT EXISTS (
     SELECT 1
       FROM ci.questions t
      WHERE t.is_active
        AND t.is_private_to IS NULL
        AND lower(btrim(t.question_text)) = lower(btrim(q.question_text))
   );

-- migrate:down
-- Put the repaired rows back the way 20260818235602 left them: retired,
-- untiered, labelled created_by_llm, under the category its step 4 folded them
-- into. Found by the same pinned ids plus the seed label the up gave them, and
-- only while nobody has answered or queued them since — a question somebody has
-- answered stays. created_at is NOT put back: the legacy value is recorded
-- nowhere. A retired row is in no rotation, so nothing moves, and re-applying
-- the up stamps the same batch time again.
UPDATE ci.questions q
   SET is_active         = false,
       is_seed_question  = false,
       created_by_llm    = true,
       answer_tier       = NULL,
       question_category = CASE q.question_category
           WHEN 'Mental & Emotional Wellbeing' THEN 'Health & Body'
           WHEN 'Family & Relationships'       THEN 'Relationships & People'
           WHEN 'Friendships & Social Life'    THEN 'Relationships & People'
           WHEN 'Career & Work'                THEN 'Work & Money'
           WHEN 'Hobbies & Leisure'            THEN 'Interests & Culture'
           WHEN 'Entertainment & Media'        THEN 'Interests & Culture'
           WHEN 'Culture & Heritage'           THEN 'Identity & Background'
           -- 'Preferences & Favorites' and 'Health & Body' fold onto themselves.
           ELSE q.question_category
         END,
       updated_at        = now()
 WHERE q.question_id IN (
    '186ddaa8-6cfc-4027-ade8-2ab6f385b249', '82ba7920-eb4b-4b40-9a30-8d80e4c72019', '2f5de921-0098-4ac3-ab11-e2b00751753b',
